-- Change only the existing server-owned gacha fee; no client-authoritative debit.
do $$declare source text;begin
 select pg_get_functiondef('public.online_world_equipment(text,jsonb)'::regprocedure) into source;
 if position('price:=100;roll:=' in source)=0 then raise exception 'Unexpected gacha price source';end if;
 execute replace(source,'price:=100;roll:=','price:=1000;roll:=');
end$$;
-- Introduce the lantern monster into saved rooms without resetting their progress.
update public.online_adventure_rooms r set snapshot=jsonb_set(r.snapshot,'{enemies}',coalesce(r.snapshot->'enemies','[]') || (select jsonb_build_array(value) from public.online_adventure_config c cross join jsonb_array_elements(c.data->'enemies') where c.id='floor1' and value->>'id'='m9')) where r.status='active' and not exists(select 1 from jsonb_array_elements(r.snapshot->'enemies') e where e->>'id'='m9');
do $$declare a online_adventure_members;r online_adventure_rooms;loot online_adventure_loot;cfg jsonb;e jsonb;home jsonb;es jsonb;i int;nx int;ny int;begin
 select data into cfg from online_adventure_config where id='floor1';
 for a in select * from online_adventure_members where finished_at is null and floor in(1,2) order by id loop
  select * into r from online_adventure_rooms where id=a.room_id;
  if public.online_adventure_blocked(a.x,a.y,a.floor,r.snapshot) then
   select x,y into nx,ny from generate_series(3,9) gx(x) cross join generate_series(case when a.floor=2 then 5 else 12 end,case when a.floor=2 then 9 else 16 end) gy(y) where not public.online_adventure_blocked(x,y,a.floor,r.snapshot) and not exists(select 1 from online_adventure_members m where m.room_id=a.room_id and m.id<>a.id and m.floor=a.floor and m.finished_at is null and m.x=gx.x and m.y=gy.y) order by abs(x-5)+abs(y-case when a.floor=2 then 8 else 14 end),y,x limit 1;
   update online_adventure_members set x=nx,y=ny where id=a.id;
  end if;
 end loop;
 for loot in select * from online_adventure_loot loop
  select * into r from online_adventure_rooms where id=loot.room_id;if public.online_adventure_blocked(loot.x,loot.y,loot.floor,r.snapshot) then
   select x,y into nx,ny from generate_series(greatest(0,loot.x-8),loot.x+8) gx(x) cross join generate_series(greatest(0,loot.y-8),loot.y+8) gy(y) where not public.online_adventure_blocked(x,y,loot.floor,r.snapshot) order by abs(x-loot.x)+abs(y-loot.y),y,x limit 1;
   if nx is not null then update online_adventure_loot set x=nx,y=ny where id=loot.id;end if;
  end if;
 end loop;
 for r in select * from online_adventure_rooms where status='active' loop
  es:=r.snapshot->'enemies';for i in 0..jsonb_array_length(es)-1 loop e:=es->i;if (e->>'hp')::int>0 and public.online_adventure_blocked((e->>'x')::int,(e->>'y')::int,1,r.snapshot) then
   select value into home from jsonb_array_elements(cfg->'enemies') where value->>'id'=e->>'id';
   select x,y into nx,ny from generate_series((home->>'x')::int-3,(home->>'x')::int+3) gx(x) cross join generate_series((home->>'y')::int-3,(home->>'y')::int+3) gy(y) where not public.online_adventure_blocked(x,y,1,r.snapshot) and not exists(select 1 from jsonb_array_elements(es) other where other->>'id'<>e->>'id' and (other->>'hp')::int>0 and (other->>'x')::int=gx.x and (other->>'y')::int=gy.y) order by abs(x-(home->>'x')::int)+abs(y-(home->>'y')::int) limit 1;
   es:=jsonb_set(es,array[i::text],e||jsonb_build_object('x',nx,'y',ny));
  end if;end loop;update online_adventure_rooms set snapshot=jsonb_set(snapshot,'{enemies}',es) where id=r.id;
 end loop;
end$$;

alter function public.online_world(text,jsonb) rename to online_world_v7;
revoke all on function public.online_world_v7(text,jsonb) from public,anon,authenticated;
create function public.online_world(action text,payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare result jsonb;me jsonb;target jsonb;q online_characters;slot text;k text;instance jsonb;items jsonb:='[]';r online_adventure_rooms;p online_presence;
begin
 -- Previous wrapper authenticates, serializes, and applies all existing validation.
 result:=public.online_world_v7(case when action='inspect_player' then 'poll' else action end,case when action='inspect_player' then '{}'::jsonb else payload end);
 if action='inspect_player' then
  select value into me from jsonb_array_elements(result->'players') where value->>'character_id'=result->'active'->>'id';
  select value into target from jsonb_array_elements(result->'players') where value->>'character_id'=payload->>'character_id';
  if me is null or target is null or abs((me->>'x')::int-(target->>'x')::int)+abs((me->>'y')::int-(target->>'y')::int)>3 then raise exception '装備を見るにはプレイヤーに近づいてください。';end if;
  select * into q from online_characters where id=(target->>'character_id')::uuid;
  foreach slot in array array['weapon','armor','shield','necklace'] loop
   if coalesce((q.gear->>slot)::boolean,false) then
    k:=coalesce(q.gear->>(slot||'_key'),case when slot='weapon' then 'w_iron_dagger' when slot='armor' then 'leather' end);if k is null then continue;end if;
    select value into instance from jsonb_array_elements(coalesce(q.instances->slot,'[]')) where value->>'id'=q.gear->>(slot||'_instance_id');
    items:=items||jsonb_build_array(jsonb_build_object('slot',slot,'key',k,'dur',instance->'dur','max',instance->'max'));
   end if;
  end loop;
  result:=result||jsonb_build_object('inspection',jsonb_build_object('name',q.name,'gender',q.gender,'hp',q.hp,'equipment',items));
 end if;
 select * into p from online_presence where user_id=auth.uid();
 if p.location='dungeon' then
  select rooms.* into r from online_adventure_rooms rooms join online_adventure_members m on m.room_id=rooms.id where m.character_id=p.character_id and m.finished_at is null;
  if r.id is not null and exists(select 1 from jsonb_array_elements(r.snapshot->'enemies') e where e->>'key'='m_mush' and (e->>'hp')::int<=0) and coalesce((r.snapshot->>'visionRadius')::int,4)<5 then
   update online_adventure_rooms set snapshot=jsonb_set(snapshot,'{visionRadius}','5') where id=r.id returning * into r;
   result:=jsonb_set(result,'{adventure,snapshot}',r.snapshot);
  end if;
 end if;
 return result;
end$$;
revoke all on function public.online_world(text,jsonb) from public,anon;
grant execute on function public.online_world(text,jsonb) to authenticated;
notify pgrst,'reload schema';
commit;
